Script.script:
-- Mudlet base UI: a small starter interface that adapts to whatever the game -- provides. Nothing is created until the game actually sends something: -- vitals gauges are built from GMCP character data (normalised across the -- dialects games speak, and only for the fields that exist), with the map and -- chat windows alongside them. Chat comes from gmcp.Comm.Channel.Text when -- the game offers it; for everything else, additive triggers capture the -- common chat-line shapes (tells, says, channels) shared by most games - so -- on a game with no GMCP at all the UI appears on the first chat line. -- Chat is sorted into All/Tells/Channels tabs, and the map pane shows a -- placeholder until the profile actually has map data. -- Gauges have their own fallback ladder when GMCP is missing: MSDP is -- negotiated quietly, self-sufficient prompt lines (labelled cur/max or -- percent) are trusted once they recur, score screens are read passively, -- and as a last resort "score" is sent once - visibly - to learn the maxima -- on games whose prompt only carries current values. -- Type "baseui" for options; "baseui hide" removes it until "baseui show".
BaseUI = BaseUI or {} BaseUI.gauges = BaseUI.gauges or {} BaseUI.usedGaugeSlots = BaseUI.usedGaugeSlots or 0 BaseUI.recentCaptures = BaseUI.recentCaptures or {} BaseUI.vitalsTriggerIds = BaseUI.vitalsTriggerIds or {} BaseUI.shapeSightings = BaseUI.shapeSightings or {} BaseUI.vitalsData = BaseUI.vitalsData or {} BaseUI.vitalsLock = BaseUI.vitalsLock or 0
local settingsFile = getMudletHomeDir() .. "/base_ui_settings.lua"
-- one dark theme for the whole dock; the accent appears only on section -- headers and the active chat tab so it stays an accent local theme = { accent = "#4fc1e9", bg = "#1b1e23", panel = "#14171c", border = "#3a4149", borderSoft = "#2b3138", text = "#e8eef4", textDim = "#96a0ab", font = "Ubuntu", }
local layout = { mapHeader = { y = "0%", height = "3%" }, map = { y = "3.5%", height = "33.5%" }, chatHeader = { y = "38.5%", height = "3%" }, tabs = { y = "42.5%", height = "3.8%" }, chat = { y = "46.3%", height = "29.7%" }, gaugeSlots = { "78%", "83.5%", "89%", "94.5%" }, gaugeHeight = "4.5%", }
local headerCss = string.format( [[background-color: transparent; border: 0px; border-bottom: 1px solid %s; padding-left: 2px;]], theme.borderSoft)
local placeholderCss = string.format( [[background-color: %s; border: 1px solid %s; border-radius: 6px;]], theme.panel, theme.borderSoft)
local tabCss = { active = string.format( [[background-color: #2b323b; border: 1px solid %s; border-bottom: 2px solid %s; border-top-left-radius: 4px; border-top-right-radius: 4px;]], theme.border, theme.accent), inactive = string.format( [[background-color: #1f242a; border: 1px solid %s; border-bottom: 2px solid %s; border-top-left-radius: 4px; border-top-right-radius: 4px;]], theme.borderSoft, theme.borderSoft), }
-- every gauge shares one look, a thin HUD line: bold value text floating -- over a transparent zone, with a slim stat-colored line along the bottom -- 30% tracking the value. The band edge is a hard gradient stop - Qt -- gradient stops don't alpha-composite, so each band is either fully -- transparent or fully opaque local function gaugeStyle(color) return string.format( [[background-color: qlineargradient(x1:0, y1:0, x2:0, y2:1, stop:0 rgba(0,0,0,0), stop:0.6999 rgba(0,0,0,0), stop:0.70 %s, stop:1 %s); border: none;]], color, color) end
local gaugeBack = gaugeStyle("#2c313a")
-- the text label spans the whole gauge; the padding floats the value text -- above the line, inset from the left edge local gaugeText = [[background-color: transparent; padding-left: 8px; padding-bottom: 9px;]]
local gaugeDefs = { hp = { front = gaugeStyle("#2f9e3f") }, mp = { front = gaugeStyle("#2f6f9e") }, xp = { front = gaugeStyle("#c28f2c") }, mv = { front = gaugeStyle("#2f9e8a") }, enemy = { front = gaugeStyle("#b23a3a") }, }
-- GMCP vitals arrive in several dialects: lowercase namespaces, maxima inside -- the vitals message or in a separate Maxstats one, and varying key names. -- Every node listed here is scanned on each update (the gmcp table keeps the -- latest message per node, so currents and maxima merge naturally even when -- they arrive separately) - supporting another dialect is one more line local vitalsNodes = { { "Char", "Vitals" }, { "char", "vitals" }, { "Char", "Maxstats" }, { "char", "maxstats" }, { "Char", "Status" }, { "char", "status" }, }
-- one row per gauge; current/max/percent list every key spelling observed in -- the wild. A percent key is a ready 0-100 value and needs no max: nl (IRE -- next-level percent) and tnlpct for xp, opponent_hp_pct and enemypct for -- enemy health. transient rows hide their gauge when the value goes away -- (the enemy died or was cleared). local vitalsStats = { { key = "hp", label = "HP", current = { "hp", "health" }, max = { "maxhp", "max_hp", "maxHp", "maxhealth", "max_health", "maxHealth" } }, { key = "mp", label = "MP", current = { "mp", "mana", "sp", "energy" }, max = { "maxmp", "max_mp", "maxMp", "maxmana", "max_mana", "maxMana", "maxsp", "max_sp", "maxSp", "maxenergy", "max_energy", "maxEnergy" } }, { key = "xp", label = "XP", percent = { "nl", "tnlpct" }, current = { "xp", "experience" }, max = { "maxxp", "max_xp", "maxXp", "maxexperience", "max_experience", "maxExperience" } }, { key = "enemy", label = "Enemy", transient = true, percent = { "opponent_hp_pct", "enemypct" } }, -- last on purpose: when a game supplies more stats than there are gauge -- slots, movement is the one to lose out { key = "mv", label = "MV", current = { "mv", "moves", "movement" }, max = { "maxmv", "max_mv", "maxMv", "maxmoves", "max_moves", "maxMoves", "maxmovement", "max_movement", "maxMovement" } }, }
-- vitals can also come from MSDP or from prompt/score lines. A source lock -- keeps them from fighting: the first source to produce a complete hp -- reading owns the gauges, and only a higher-ranked source can take them -- over - so gauges built from a prompt hand themselves to GMCP whenever it -- turns up, however late local sourceRanks = { gmcp = 3, msdp = 2, prompt = 1 }
-- the vitalsStats rows again, keyed by the conventional MSDP variable names local msdpStats = { { key = "hp", current = "HEALTH", max = "HEALTH_MAX" }, { key = "mp", current = "MANA", max = "MANA_MAX" }, { key = "xp", current = "EXPERIENCE", max = "EXPERIENCE_MAX" }, { key = "mv", current = "MOVEMENT", max = "MOVEMENT_MAX" }, { key = "enemy", current = "OPPONENT_HEALTH", max = "OPPONENT_HEALTH_MAX", transient = true }, }
local function gmcpNode(path) local node = gmcp for _, key in ipairs(path) do if type(node) ~= "table" then return nil end node = node[key] end if type(node) == "table" then return node end end
-- some games send numbers as strings, hence the tonumber()s; nested -- cur/max tables (vitals.hp = { cur = 10, max = 20 }) are handled too local function statReading(sources, stat) local current, max, percent for _, source in ipairs(sources) do for _, name in ipairs(stat.percent or {}) do percent = percent or tonumber(source[name]) end for _, name in ipairs(stat.current or {}) do local value = source[name] if type(value) == "table" then current = current or tonumber(value.cur) max = max or tonumber(value.max) else current = current or tonumber(value) end end for _, name in ipairs(stat.max or {}) do max = max or tonumber(source[name]) end end return current, max, percent end
-- generic chat capture for games without GMCP chat: trigger shapes most games -- share. Capture is additive - the matched line is copied into the chat window -- with its colours and never removed from the main one. -- a "[tag]", "(tag)" or "< tag |" prefix only counts as chat when its first -- word is a well-known channel name - extend this list to cover more games BaseUI.chatChannelNames = { chat = true, say = true, tell = true, tells = true, gtell = true, newbie = true, newbies = true, gossip = true, grats = true, gratz = true, congrats = true, ooc = true, ic = true, clan = true, guild = true, order = true, house = true, city = true, market = true, auction = true, trade = true, talk = true, ask = true, answer = true, question = true, questions = true, music = true, quote = true, roleplay = true, rp = true, imm = true, group = true, party = true, team = true, shout = true, yell = true, form = true, town = true, }
-- The same shapes as the "Mudlet base UI chat capture" trigger tree, in the -- same order (StarterUiTriggerCostTest compares them index by index): the tree -- routes chat, this copy tells the vitals layer which lines are conversation. -- tagged = true means the shape captures a channel tag that must pass the -- list above. local chatPatterns = { { regex = [=[^\w[\w'-]* tells you\b[^,:]{0,30}(?::|,?\s*['"])]=] }, { regex = [=[^You tell [\w'-]+[^,:]{0,30}(?::|,?\s*['"])]=] }, { regex = [=[^You tell the (?:group|formation)\b]=] }, { regex = [=[^\w[\w'-]* whispers to you\b[^,:]{0,30}(?::|,?\s*['"])]=] }, { regex = [=[^\w[\w'-]* tells the (?:group|formation)\b]=] }, { regex = [=[^You gossip[^,:]{0,20}(?::|,?\s*['"])]=] }, { regex = [=[^\w[\w'-]* (?:says|asks|exclaims)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^You (?:say|ask|exclaim)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^\w[\w'-]* (?:yells|shouts)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^You (?:yell|shout)[^,:]{0,20},?\s*['"]]=] }, { regex = [=[^\[([\w][\w -]{0,18})\]]=], tagged = true }, { regex = [=[^\(([\w -]{1,18})\)[:\s]]=], tagged = true }, { regex = [=[^< ?([\w -]{1,18}) ?\|]=], tagged = true }, }
local chatTabs = { { key = "all", label = "All" }, { key = "tells", label = "Tells" }, { key = "channels", label = "Channels" }, }
function BaseUI.routeChatLine(family) -- several shapes can match the same line - copy it only once if BaseUI.gmcpChat or BaseUI.dormant() or getLineNumber() == BaseUI.lastChatLine then return end BaseUI.lastChatLine = getLineNumber() selectCurrentLine() copy() deselect() local firstBuild = not BaseUI.container BaseUI.build() if firstBuild then -- building resizes the main window, which can renumber lines; refresh the -- marker so other patterns matching this same line stay deduplicated BaseUI.lastChatLine = getLineNumber() end if not BaseUI.chats then return end BaseUI.chats.all:appendBuffer() BaseUI.noteChatActivity("all") if family and BaseUI.chats[family] then BaseUI.chats[family]:appendBuffer() BaseUI.noteChatActivity(family) end BaseUI.checkMapData() table.insert(BaseUI.recentCaptures, { text = line, time = getEpoch() }) if #BaseUI.recentCaptures > 10 then table.remove(BaseUI.recentCaptures, 1) end end
function BaseUI.routeTaggedChatLine(tag) tag = type(tag) == "string" and tag:match("(%S+)") if not tag then return end tag = tag:lower() if not BaseUI.chatChannelNames[tag] then return end local family = (tag == "tell" or tag == "tells" or tag == "gtell") and "tells" or "channels" BaseUI.routeChatLine(family) end
-- renaming these in the trigger tree means renaming them here local chatTree = "Mudlet base UI chat capture" local chatGates = { "BaseUI chat: tells", "BaseUI chat: speech", "BaseUI chat: channel tags" }
-- a gate reached through a switched-off folder is not armed whatever its own -- flag says, and enableTrigger() only reports that it found the name - hence -- the ancestor check local function gateArmed(gate) return isActive(gate, "trigger", true) > 0 end
-- enableTrigger and disableTrigger can only name a trigger, and a name is not -- unique: copying this tree in the editor reproduces every name exactly, so -- switching ours would switch the player's copy too. Only the folder is ever -- named here, which keeps a copied gate out of it, and when the folder name -- itself is shared the layer stops switching altogether - routeChatLine() -- re-checks gmcpChat and dormant() on every line, so what is captured stays -- right either way. All that is lost is the scans disarming would have saved. function BaseUI.chatTreeShared() return exists(chatTree, "trigger") ~= 1 end
function BaseUI.armChatTriggers() if BaseUI.dormant() or BaseUI.gmcpChat then return end if BaseUI.chatTreeShared() then BaseUI.reportSharedChatTree() return end enableTrigger(chatTree) for _, gate in ipairs(chatGates) do if not gateArmed(gate) then BaseUI.reportDeadChatGate(gate) end end end
function BaseUI.reportSharedChatTree() if BaseUI.warnedSharedChatTree then return end BaseUI.warnedSharedChatTree = true debugc("[ Mudlet UI ] more than one trigger is called \"" .. chatTree .. "\", so the chat capture is left switched on rather than risk switching yours") end
-- debugc alone would not do: it writes to the editor's error console, which is -- hidden until the player goes looking for it, and is dropped entirely if the -- editor was never opened. The player-facing line is once per session, because -- arming runs again on every reconnect. function BaseUI.reportDeadChatGate(gate) debugc("[ Mudlet UI ] chat capture gate \"" .. gate .. "\" did not come up, so those lines will not be captured") if BaseUI.warnedDeadChatGate then return end BaseUI.warnedDeadChatGate = true cecho("\n<dim_grey>[ Mudlet UI ] Part of the chat capture is switched off, so some chat may not appear here - type <yellow>baseui<dim_grey> for options.<reset>\n") end
function BaseUI.disarmChatTriggers() if BaseUI.chatTreeShared() then BaseUI.reportSharedChatTree() return end disableTrigger(chatTree) end
function BaseUI.chatTriggersArmed() for _, gate in ipairs(chatGates) do if not gateArmed(gate) then return false end end return true end
-- vitals from plain text, for games that offer no protocol at all. Only -- self-sufficient shapes may drive a gauge: a labelled cur/max pair, a -- labelled percentage, or a labelled score-screen line - current-only -- prompts never invent a maximum. kind = "bare" rows exist to recognise -- those current-only prompts: they update currents once a maximum is known -- and arm the one-time auto-"score" request, nothing more. gated rows only -- go live after matching on three separate lines (prompts recur; chat -- mentions do not); score-screen rows are trusted on first sight because a -- score may only ever be shown once, and each one is anchored to line -- structure only a score screen has; windowed rows have no anchor at all -- and are trusted only for a few seconds after a "score" command really -- went to the game. -- two disambiguation lookbehinds recur below. On label-after shapes, -- numberFirstGuard keeps the numbers of a label-first reading from being -- claimed by the NEXT label ("HP: 523/600 MP: ..." must not read as -- 523/600 mp). On label-first shapes, labelFirstGuard keeps a label that -- closes a label-after reading from opening a new one ("87%hp 80%m" must -- not read as hp 80). Aligned tables pad with runs of spaces, and PCRE -- lookbehinds cannot be variable-length, so each guard spells out the run -- lengths (up to 8) as fixed-length alternatives. local numberFirstGuard = [=[(?<![\d:=])(?<![:=][ ]|[:=][ ]{2}|[:=][ ]{3}|[:=][ ]{4}|[:=][ ]{5}|[:=][ ]{6}|[:=][ ]{7}|[:=][ ]{8})]=] local labelFirstGuard = [=[(?<![\d%])(?<!\d[ ]|\d[ ]{2}|\d[ ]{3}|\d[ ]{4}|\d[ ]{5}|\d[ ]{6}|\d[ ]{7}|\d[ ]{8})]=]
-- Add label spellings here rather than inline in a shape below: anyVitalsLabel -- is built from these tables, and a spelling that only exists inline is missing -- from the prefilter, so the shape never sees a line to read. local promptLabels = { hp = [=[hp|health|hits?]=], mp = [=[mp|mana|sp|magic|energy]=], mv = [=[mv|moves?|movement|end(?:urance)?|st(?:amina)?]=], xp = [=[xp|exp|tnl]=], } -- percentages and current-only prompts need the conservative spellings: a -- looser one turns ordinary prose into a reading local coreLabels = { hp = [=[hp|health]=], mp = [=[mp|mana|sp]=], } -- what a terse prompt abbreviates to once the number has been read: "523h" local shortLabels = { hp = [=[h(?:p|its?)?]=], mp = [=[m(?:p|ana)?]=], mv = [=[mv|moves?]=], }
-- score screens across the codebase families (Diku/Merc/ROM, Circle/tbaMUD, -- SMAUG, LPMud, IRE, Aardwolf...) share a handful of label spellings per -- stat; the sets below feed every score-screen shape. Unlike prompts, score -- screens write big numbers with thousands separators ("3,600"), so the -- number shape accepts them local scoreNumber = [=[(\d{1,3}(?:,\d{3})+|\d+)]=] local slashPair = scoreNumber .. [=[\s*/\s*]=] .. scoreNumber -- Circle/tbaMUD and LPMuds write "current(max)" instead of "current/max" local parenPair = scoreNumber .. [=[\s*\(\s*]=] .. scoreNumber .. [=[\s*\)]=] -- the SMAUG family writes "current of max" ("Hitpoints: 90 of 90") local ofPair = scoreNumber .. [=[\s+of\s+]=] .. scoreNumber local scoreLabels = { hp = [=[(?:health|hit\s*points?|hits?|hp)]=], mp = [=[(?:mana|magic|spell\s*points?|energy|blood|sp|mp)]=], mv = [=[(?:move(?:ment)?s?(?:\s*points?)?|stamina|endurance|vitality|mv)]=], xp = [=[(?:exp(?:erience)?(?:\s*points?)?|xp)]=], } local anyScoreLabel = [=[(?:]=] .. scoreLabels.hp .. [=[|]=] .. scoreLabels.mp .. [=[|]=] .. scoreLabels.mv .. [=[|]=] .. scoreLabels.xp .. [=[)]=] -- Aardwolf brackets its values ("Hit : [ 168/168 ]"), so a "[" may -- open any pair local pairLeadIn = [=[\s*[:=\]]+\s*\[?\s*]=] -- a line counts as a score-table row when it opens with a labelled vital -- ("Health: 3600/3600 Mana: 3400/3400", "| Health : 3600/3600 |"), with a -- table border whose first cell is some labelled number ("| Level: 201 -- Hit Points: 500/500 |"), or with any short "Label: number" cell the way -- SMAUG's dashboard rows do ("PRACT: 005 Hitpoints: 90 of 90"). -- Chat and prose do not open like this, which is what lets the row shapes -- read their labels ANYWHERE on such a line while still being trusted on -- first sight local scoreRowAnchor = [=[(?i)^(?=[^\w\r\n]{0,12}]=] .. anyScoreLabel .. [=[\s*[:=\]]|\s{0,8}[|│┃║+#*!]{1,2}[-= ]{0,10}[\w' .]{1,18}[:=\]]+\s*\[?\s*[\d,]|[a-z][\w' .]{0,14}\s*:\s*\[?\s*[\d,])]=] local function scoreRow(stat, pair) return scoreRowAnchor .. [=[.*?\b]=] .. scoreLabels[stat] .. pairLeadIn .. pair end -- a vital label sitting right after a table border is a score cell wherever -- the row itself starts ("| Race: Undead Atavian | Health: 4252/4252 |") local function scoreCell(stat, pair) return [=[(?i)[|│┃║]\s*]=] .. scoreLabels[stat] .. pairLeadIn .. pair end -- no anchor at all: only trusted inside the short window after a "score" -- command actually went to the game (see BaseUI.noteCommandSent) - which is -- the moment layouts with nothing else to anchor on (AFKMud's "Race : Human -- Mana : 1000/1000" rows) really are score output local function scoreWindowed(stat, pair) return [=[(?i)\b]=] .. scoreLabels[stat] .. pairLeadIn .. pair end -- Diku/Merc/ROM and Circle/tbaMUD score screens are sentences: "You have -- 100/100 hit, 90/90 mana, and 100/100 movement points." The anchor demands -- a number right after "You have" (so "You have collected 5/6 mana -- crystals" stays prose) and the tail demands the sentence move on to the -- next stat or wind down ("5/6 mana potions" stays prose too) local youHave = [=[(?i)^you\s+have\s+(?=[\d,]+\s*[(/])]=] local sentenceTail = [=[\s*(?:points?\s*)?(?:[,.;)]|and\b|left\b|remaining\b|$)]=] local sentenceLabels = { hp = [=[(?:hit\s*points?|hits?)]=], mp = [=[(?:mana|magic|spell\s*points?)]=], mv = [=[(?:move(?:ment)?s?|stamina|endurance)]=], } local function scoreSentence(stat, pair) return youHave .. [=[.*?\b]=] .. pair .. [=[\s*]=] .. sentenceLabels[stat] .. sentenceTail end
-- The single trigger fronting every shape below. Its one contract: it must -- match every line a shape reads a value from, or that game's gauges silently -- never appear. Being loose the other way only costs a Lua shape walk, so keep -- it loose - "the orc hits you for 12 damage" gets through and that is fine. -- -- (?<![a-z]) / (?![a-z]) rather than \b: a label may abut its number -- ("hp100/120"), which is not a word boundary. The optional "points" tail is -- for score sentences that run the two together ("100/120 manapoints"). local anyVitalsLabel = table.concat({ promptLabels.hp, promptLabels.mp, promptLabels.mv, promptLabels.xp, coreLabels.hp, coreLabels.mp, shortLabels.hp, shortLabels.mp, shortLabels.mv, scoreLabels.hp, scoreLabels.mp, scoreLabels.mv, scoreLabels.xp, sentenceLabels.hp, sentenceLabels.mp, sentenceLabels.mv, -- two prompt shapes spell a lone "m" for mana inline [=[m]=], }, "|") BaseUI.vitalsPrefilter = [=[(?i)(?<![a-z])(?:]=] .. anyVitalsLabel .. [=[)(?:\s*points?)?(?![a-z])]=]
local vitalsLinePatterns = { -- self-sufficient prompt shapes: cur/max with the label after the numbers { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)\s*/\s*(\d+)\s*(?:]=] .. promptLabels.hp .. [=[)\b]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)\s*/\s*(\d+)\s*(?:]=] .. promptLabels.mp .. [=[|m)\b]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)\s*/\s*(\d+)\s*(?:]=] .. promptLabels.mv .. [=[)\b]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)\s*/\s*(\d+)\s*(?:]=] .. promptLabels.xp .. [=[)\b]=] }, -- self-sufficient prompt shapes: cur/max with the label first. The -- explicit-separator form is trusted anywhere; the separator-less form -- needs the digit lookbehinds so "523/600 hp ..." cannot have its own -- trailing label re-read as the start of a new reading { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. promptLabels.hp .. [=[)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "hp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. promptLabels.hp .. [=[)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. promptLabels.mp .. [=[)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. promptLabels.mp .. [=[)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. promptLabels.mv .. [=[)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "mv", kind = "curmax", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. promptLabels.mv .. [=[)\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. promptLabels.xp .. [=[)[:=]\s*(\d+)\s*/\s*(\d+)]=] }, { stat = "xp", kind = "curmax", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. promptLabels.xp .. [=[)\s*(\d+)\s*/\s*(\d+)]=] }, -- labelled percentages need no maximum at all { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)%\s*(?:]=] .. coreLabels.hp .. [=[)\b]=] }, { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. coreLabels.hp .. [=[)[:=]\s*(\d+)%]=] }, { stat = "hp", kind = "percent", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. coreLabels.hp .. [=[)\s*(\d+)%]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)]=] .. numberFirstGuard .. [=[(\d+)%\s*(?:]=] .. coreLabels.mp .. [=[|m)\b]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)(?<!%)\b(?:]=] .. coreLabels.mp .. [=[)[:=]\s*(\d+)%]=] }, { stat = "mp", kind = "percent", gated = true, regex = [=[(?i)]=] .. labelFirstGuard .. [=[\b(?:]=] .. coreLabels.mp .. [=[)\s*(\d+)%]=] }, -- score-screen shapes, all trusted on first sight. A single labelled row, -- with or without a separator, possibly behind table borders: -- "Health : 523/600", "| Hit Points 3,600/3,600 |" { stat = "hp", kind = "curmax", regex = [=[(?i)^[^\w\r\n]{0,12}]=] .. scoreLabels.hp .. [=[\s*[:=\]]*\s*]=] .. slashPair }, { stat = "mp", kind = "curmax", regex = [=[(?i)^[^\w\r\n]{0,12}]=] .. scoreLabels.mp .. [=[\s*[:=\]]*\s*]=] .. slashPair }, { stat = "mv", kind = "curmax", regex = [=[(?i)^[^\w\r\n]{0,12}]=] .. scoreLabels.mv .. [=[\s*[:=\]]*\s*]=] .. slashPair }, { stat = "xp", kind = "curmax", regex = [=[(?i)^[^\w\r\n]{0,12}]=] .. scoreLabels.xp .. [=[\s*[:=\]]*\s*]=] .. slashPair }, -- score-table rows read their labels anywhere on the line (the anchor in -- scoreRow decides what counts as a row): "Health: 3600/3600 Mana: -- 3400/3400" (IRE), "| Level: 201 ... Hit Points: 500/500 |" (Aardwolf), -- "Hp: 143 (167) Gp: 240 (240)" (LPMud/Discworld) { stat = "hp", kind = "curmax", regex = scoreRow("hp", slashPair) }, { stat = "mp", kind = "curmax", regex = scoreRow("mp", slashPair) }, { stat = "mv", kind = "curmax", regex = scoreRow("mv", slashPair) }, { stat = "xp", kind = "curmax", regex = scoreRow("xp", slashPair) }, { stat = "hp", kind = "curmax", regex = scoreRow("hp", parenPair) }, { stat = "mp", kind = "curmax", regex = scoreRow("mp", parenPair) }, { stat = "mv", kind = "curmax", regex = scoreRow("mv", parenPair) }, { stat = "hp", kind = "curmax", regex = scoreRow("hp", ofPair) }, { stat = "mp", kind = "curmax", regex = scoreRow("mp", ofPair) }, { stat = "mv", kind = "curmax", regex = scoreRow("mv", ofPair) }, -- bordered cells (IRE, Aardwolf): the label follows a "|" mid-line { stat = "hp", kind = "curmax", regex = scoreCell("hp", slashPair) }, { stat = "mp", kind = "curmax", regex = scoreCell("mp", slashPair) }, { stat = "mv", kind = "curmax", regex = scoreCell("mv", slashPair) }, { stat = "xp", kind = "curmax", regex = scoreCell("xp", slashPair) }, { stat = "hp", kind = "curmax", regex = scoreCell("hp", parenPair) }, { stat = "mp", kind = "curmax", regex = scoreCell("mp", parenPair) }, { stat = "mv", kind = "curmax", regex = scoreCell("mv", parenPair) }, { stat = "hp", kind = "curmax", regex = scoreCell("hp", ofPair) }, { stat = "mp", kind = "curmax", regex = scoreCell("mp", ofPair) }, { stat = "mv", kind = "curmax", regex = scoreCell("mv", ofPair) }, -- Diku/Merc/ROM and Circle/tbaMUD score sentences: "You have 100/100 -- hit, 90/90 mana, and 100/100 movement points." (Diku and Circle write -- "100(100)" instead of "100/100") { stat = "hp", kind = "curmax", regex = scoreSentence("hp", slashPair) }, { stat = "mp", kind = "curmax", regex = scoreSentence("mp", slashPair) }, { stat = "mv", kind = "curmax", regex = scoreSentence("mv", slashPair) }, { stat = "hp", kind = "curmax", regex = scoreSentence("hp", parenPair) }, { stat = "mp", kind = "curmax", regex = scoreSentence("mp", parenPair) }, { stat = "mv", kind = "curmax", regex = scoreSentence("mv", parenPair) }, { stat = "hp", kind = "curmax", regex = [=[(?i)]=] .. slashPair .. [=[\s*hit points\b]=] }, -- LPMud 2.4.5 writes current, label, then the max: "50 hit points(50)." { stat = "hp", kind = "curmax", regex = [=[(?i)\b]=] .. scoreNumber .. [=[\s*hit\s*points?\s*\(\s*]=] .. scoreNumber .. [=[\s*\)]=] }, -- anchorless labelled pairs, only live inside the post-"score" window { stat = "hp", kind = "curmax", windowed = true, regex = scoreWindowed("hp", slashPair) }, { stat = "mp", kind = "curmax", windowed = true, regex = scoreWindowed("mp", slashPair) }, { stat = "mv", kind = "curmax", windowed = true, regex = scoreWindowed("mv", slashPair) }, { stat = "xp", kind = "curmax", windowed = true, regex = scoreWindowed("xp", slashPair) }, { stat = "hp", kind = "curmax", windowed = true, regex = scoreWindowed("hp", parenPair) }, { stat = "mp", kind = "curmax", windowed = true, regex = scoreWindowed("mp", parenPair) }, { stat = "mv", kind = "curmax", windowed = true, regex = scoreWindowed("mv", parenPair) }, { stat = "hp", kind = "curmax", windowed = true, regex = scoreWindowed("hp", ofPair) }, { stat = "mp", kind = "curmax", windowed = true, regex = scoreWindowed("mp", ofPair) }, { stat = "mv", kind = "curmax", windowed = true, regex = scoreWindowed("mv", ofPair) }, -- current-only prompt shapes; the lookarounds keep them off cur/max and -- percentage lines, which belong to the shapes above { stat = "hp", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*]=] .. shortLabels.hp .. [=[\b(?!\s*[/%])]=] }, { stat = "hp", kind = "bare", gated = true, regex = [=[(?i)\b(?:]=] .. promptLabels.hp .. [=[)[:=]\s*(\d+)\b(?!\s*[/%.])]=] }, { stat = "mp", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*]=] .. shortLabels.mp .. [=[\b(?!\s*[/%])]=] }, { stat = "mp", kind = "bare", gated = true, regex = [=[(?i)\b(?:]=] .. coreLabels.mp .. [=[)[:=]\s*(\d+)\b(?!\s*[/%.])]=] }, { stat = "mv", kind = "bare", gated = true, regex = [=[(?i)(?<![\d/.,:%])(\d+)\s*(?:]=] .. shortLabels.mv .. [=[)\b(?!\s*[/%])]=] }, }
-- rex.match given a pattern STRING compiles it afresh on every call, and a line -- reaching this layer is tested against up to 77 shapes. Never pass .regex to -- rex.match directly. local compiledPattern = setmetatable({}, { __index = function(cache, regex) local ok, compiled = pcall(rex.new, regex) if not ok then -- keep the string so rex.match still raises on it rather than the shape -- vanishing; the error is only precise here, not once per line debugc("[ Mudlet UI ] a vitals/chat shape would not compile, falling back to per-line compilation: " .. tostring(compiled) .. " in: " .. regex) end local value = ok and compiled or regex rawset(cache, regex, value) return value end, })
-- for the test suite: how many shapes parseVitalsLine walks function BaseUI.vitalsShapeCount() return #vitalsLinePatterns end
-- for the test suite: the shapes chatLikeLine() walks, so a corpus can be held -- to cover them all function BaseUI.chatShapeRegexes() local regexes = {} for _, pattern in ipairs(chatPatterns) do regexes[#regexes + 1] = pattern.regex end return regexes end
-- for the test suite: the fallback above still works, so only an explicit check -- notices a shape that fell back to per-line compilation function BaseUI.shapesArePrecompiled() for _, list in ipairs({ chatPatterns, vitalsLinePatterns }) do for _, pattern in ipairs(list) do if type(compiledPattern[pattern.regex]) ~= "userdata" then return false end end end return true end
-- lines the chat layer would route are never harvested for vitals - a tell -- saying "I am on 100/120 hp" is conversation, not a prompt function BaseUI.chatLikeLine(text) for _, pattern in ipairs(chatPatterns) do local capture = rex.match(text, compiledPattern[pattern.regex]) if capture then if not pattern.tagged then return true end local tag = type(capture) == "string" and capture:match("(%S+)") if tag and BaseUI.chatChannelNames[tag:lower()] then return true end end end return false end
-- score screens write numbers with thousands separators; strip them before -- converting local function parseVitalsNumber(text) if not text then return nil end return tonumber((text:gsub(",", ""))) end
-- readings above this are ids, timestamps or garbage, never vitals local maxSaneVital = 1e10 -- overhealing exists, so current may exceed max - but not tenfold local maxOverhealFactor = 10
-- pure so the test suite can drive it: turns one plain-text line into a list -- of { stat, kind, current, max, percent, pattern, gated, windowed } -- readings (kind "bare" means a current with no maximum; gated rows need -- the recurrence gate in BaseUI.onVitalsLine before they may drive a gauge, -- windowed rows the post-"score" window). Chat-shaped lines yield nothing. -- Nonsense readings - a max of zero, a wildly overhealed current, absurd -- magnitudes - are dropped here so a score-screen misread can never paint a -- broken gauge. function BaseUI.parseVitalsLine(text) local readings = {} if type(text) ~= "string" or BaseUI.chatLikeLine(text) then return readings end for index, pattern in ipairs(vitalsLinePatterns) do local first, second = rex.match(text, compiledPattern[pattern.regex]) local reading if pattern.kind == "curmax" and first then local current, max = parseVitalsNumber(first), parseVitalsNumber(second) if current and max and max > 0 and max < maxSaneVital and current <= max * maxOverhealFactor then reading = { stat = pattern.stat, kind = pattern.kind, current = current, max = max } end elseif pattern.kind == "percent" and first then local percent = tonumber(first) if percent and percent <= 100 then reading = { stat = pattern.stat, kind = pattern.kind, percent = percent } end elseif pattern.kind == "bare" and first then local current = tonumber(first) if current and current < maxSaneVital then reading = { stat = pattern.stat, kind = pattern.kind, current = current } end end if reading then reading.pattern = index reading.gated = pattern.gated reading.windowed = pattern.windowed table.insert(readings, reading) end end return readings end
function BaseUI.scoreWindowOpen() return BaseUI.scoreWindowUntil ~= nil and getEpoch() < BaseUI.scoreWindowUntil end
-- lastChatLine keeps a line the chat layer routed out of the vitals layer; the -- refresh after applyVitals is because building the dock rewraps the buffer and -- renumbers lines, which would otherwise leave the marker on an unrelated line function BaseUI.onVitalsLine() local lineNumber = getLineNumber() if lineNumber == BaseUI.lastVitalsLine or lineNumber == BaseUI.lastChatLine then return end BaseUI.lastVitalsLine = lineNumber local updates = {} local windowOpen = BaseUI.scoreWindowOpen() for _, reading in ipairs(BaseUI.parseVitalsLine(line)) do local live = true if reading.windowed then live = windowOpen elseif reading.gated then local seen = (BaseUI.shapeSightings[reading.pattern] or 0) + 1 BaseUI.shapeSightings[reading.pattern] = seen live = seen >= 3 end if live then if reading.kind == "bare" then BaseUI.maybeRequestScore() end local update = updates[reading.stat] or {} update.current = reading.current or update.current update.max = reading.max or update.max update.percent = reading.percent or update.percent updates[reading.stat] = update end end if next(updates) then BaseUI.applyVitals("prompt", updates) -- building the dock resizes the main window, which can renumber lines; -- refresh the marker so other patterns on this same line stay deduplicated BaseUI.lastVitalsLine = getLineNumber() end end
-- applyVitals discards prompt readings once a protocol holds the lock, so the -- plain-text layer is pure per-line cost from then on function BaseUI.structuredVitalsOwnGauges() return BaseUI.vitalsLock >= sourceRanks.msdp end
function BaseUI.createVitalsTriggers() if BaseUI.dormant() or BaseUI.structuredVitalsOwnGauges() or next(BaseUI.vitalsTriggerIds) then return end BaseUI.vitalsTriggerIds = { tempRegexTrigger(BaseUI.vitalsPrefilter, BaseUI.onVitalsLine) } end
function BaseUI.killVitalsTriggers() for _, id in ipairs(BaseUI.vitalsTriggerIds) do killTrigger(id) end BaseUI.vitalsTriggerIds = {} end
-- last rung of the ladder: a game whose prompt only carries currents gets -- asked for its score screen - once per session, visibly, and only when no -- protocol has offered vitals and no maximum is known yet. The score output -- is picked up by the always-on score-screen shapes; if it teaches us -- nothing, that is the end of it - no retry, no error. function BaseUI.maybeRequestScore() if BaseUI.scoreRequested or BaseUI.sawGmcpVitals or BaseUI.sawMsdpVitals then return end local hp = BaseUI.vitalsData.hp if hp and (hp.max or hp.percent) then return end local _, _, connected = getConnectionInfo() if not connected then return end BaseUI.scoreRequested = true send("score") cecho("\n<cyan>[ Mudlet UI ] Sent \"score\" once to size your gauges - type <yellow>baseui<cyan> to adjust.<reset>\n") end
-- whenever a "score" command actually goes to the game - ours above, or the -- player typing it - the next few seconds of output ARE the score screen, -- so the anchorless windowed shapes may be trusted for that long. This is -- what reads layouts with nothing structural to anchor on. function BaseUI.noteCommandSent(_, command) if type(command) ~= "string" then return end command = command:trim():lower() if command == "score" or command == "sc" then BaseUI.scoreWindowUntil = getEpoch() + 10 end end
function BaseUI.loadSettings() BaseUI.settings = {} if io.exists(settingsFile) and not pcall(table.load, settingsFile, BaseUI.settings) then -- corrupted settings file - start over with the defaults, but say so BaseUI.settings = {} cecho("\n<dim_grey>[ Mudlet UI ] Could not read the saved settings - using the defaults.<reset>\n") end end
function BaseUI.saveSettings() table.save(settingsFile, BaseUI.settings) end
-- the UI keeps out of the way either when the user hid it or when the game -- installed an interface of its own ("standing aside") function BaseUI.dormant() return BaseUI.settings.hidden or BaseUI.settings.standingAside ~= nil end
-- a game that supplies its own interface wins: the moment Mudlet installs a -- Client.GUI package the starter UI stands aside - capture triggers retired, -- dock hidden - and stays aside in later sessions. Deliberately silent: the -- game's own install is announcement enough, and "baseui show" (surfaced by -- the "baseui" status alias) is the way back for players who prefer this UI. function BaseUI.standAside(_, packageName) BaseUI.settings.standingAside = packageName or "the game's interface" BaseUI.saveSettings() BaseUI.disarmChatTriggers() BaseUI.killVitalsTriggers() if BaseUI.container then BaseUI.container:hide() BaseUI.container:adjustBorder() end end
-- if the game's interface is later uninstalled, quietly return to duty. Not -- straight away though: a version upgrade uninstalls only to reinstall a -- moment later, so look again once the dust has settled function BaseUI.serverGuiRemoved(_, packageName) if not BaseUI.settings.standingAside or packageName ~= BaseUI.settings.standingAside then return end tempTimer(10, function() local aside = BaseUI.settings.standingAside if not aside or table.contains(getPackages(), aside) then return end BaseUI.settings.standingAside = nil BaseUI.saveSettings() BaseUI.armChatTriggers() BaseUI.createVitalsTriggers() BaseUI.renderVitals() end) end
function BaseUI.sectionHeader(name, text, spot) local label = Geyser.Label:new({ name = name, x = "0%", y = spot.y, width = "100%", height = spot.height, font = theme.font, fontSize = 9, fgColor = theme.accent, format = "lb", }, BaseUI.container) label:setStyleSheet(headerCss) label:echo(text:upper()) return label end
function BaseUI.mapHasData() return next(getRooms()) ~= nil end
function BaseUI.createMapper() BaseUI.map = Geyser.Mapper:new({ name = "BaseUI_map", x = "0%", y = layout.map.y, width = "100%", height = layout.map.height, }, BaseUI.container) end
-- the embedded mapper shows a clipped "load or create a map" widget while the -- profile has no map data, so a placeholder holds its spot until the first -- room exists (made by a mapping script, a map download or a manual load). -- Cheap to poll: getRooms() stays empty right up until the swap happens. function BaseUI.checkMapData() if not BaseUI.container or BaseUI.map or BaseUI.dormant() then return end if not BaseUI.mapHasData() then return end if BaseUI.mapPlaceholder then BaseUI.mapPlaceholder:hide() end BaseUI.createMapper() end
function BaseUI.build() if BaseUI.container then return end BaseUI.container = Adjustable.Container:new({ name = "BaseUI", x = "75%", y = "0%", width = "25%", height = "100%", attached = "right", titleText = "Mudlet UI", titleTxtColor = theme.text, adjLabelstyle = string.format("background-color: %s; border: 1px solid %s;", theme.bg, theme.border), buttonstyle = string.format( [[QLabel{ border-color: %s; background-color: %s; } QLabel::hover{ background-color: rgba(90,100,110,50%%); }]], theme.border, theme.bg), -- the container's own session persistence can restore a hidden, detached -- state that is impossible to bring back reliably - we persist the only -- choice that matters (hidden or not) ourselves autoLoad = false, autoSave = false, }) BaseUI.mapHeader = BaseUI.sectionHeader("BaseUI_map_header", "Map", layout.mapHeader) if BaseUI.mapHasData() then BaseUI.createMapper() else BaseUI.mapPlaceholder = Geyser.Label:new({ name = "BaseUI_map_placeholder", x = "0%", y = layout.map.y, width = "100%", height = layout.map.height, font = theme.font, fontSize = 10, fgColor = theme.textDim, format = "c", }, BaseUI.container) BaseUI.mapPlaceholder:setStyleSheet(placeholderCss) BaseUI.mapPlaceholder:echo("Your map will appear<br>here as you explore") end BaseUI.chatHeader = BaseUI.sectionHeader("BaseUI_chat_header", "Chat", layout.chatHeader) BaseUI.chats = {} BaseUI.chatTabLabels = {} BaseUI.unread = { all = 0, tells = 0, channels = 0 } BaseUI.activeChatTab = "all" local tabX = { "0%", "34%", "68%" } for i, tab in ipairs(chatTabs) do local label = Geyser.Label:new({ name = "BaseUI_tab_" .. tab.key, x = tabX[i], y = layout.tabs.y, width = "32%", height = layout.tabs.height, font = theme.font, fontSize = 9, format = "c", }, BaseUI.container) label:setClickCallback(BaseUI.selectChatTab, tab.key) BaseUI.chatTabLabels[tab.key] = label local console = Geyser.MiniConsole:new({ name = "BaseUI_chat_" .. tab.key, x = "0%", y = layout.chat.y, width = "100%", height = layout.chat.height, autoWrap = true, -- plain black so trigger-captured lines (which keep the main console's -- background colour) blend in seamlessly color = "black", fontSize = 10, }, BaseUI.container) BaseUI.chats[tab.key] = console if tab.key ~= "all" then console:hide() end end BaseUI.chat = BaseUI.chats.all BaseUI.refreshChatTabs() BaseUI.chats.all:decho("<150,158,167>Tells, says and channel chat from the game will be collected here.\n") -- the container remembers its own hidden/detached state from the previous -- session (it saves on exit) - our setting says it should be visible, so -- override whatever it restored if not BaseUI.dormant() then BaseUI.container:show() if not BaseUI.container.attached then BaseUI.container:attachToBorder("right") end end BaseUI.maybeAnnounce() end
function BaseUI.refreshChatTabs() for _, tab in ipairs(chatTabs) do local label = BaseUI.chatTabLabels and BaseUI.chatTabLabels[tab.key] if label then local active = BaseUI.activeChatTab == tab.key label:setStyleSheet(active and tabCss.active or tabCss.inactive) local text = tab.label local unread = BaseUI.unread[tab.key] if unread > 0 and not active then text = string.format("%s (%d)", tab.label, math.min(unread, 99)) end label:echo(text, active and theme.text or theme.textDim) end end end
function BaseUI.selectChatTab(key) if not BaseUI.chats or not BaseUI.chats[key] then return end BaseUI.activeChatTab = key BaseUI.unread[key] = 0 for _, tab in ipairs(chatTabs) do local console = BaseUI.chats[tab.key] if tab.key == key then console:show() else console:hide() end end BaseUI.refreshChatTabs() end
function BaseUI.noteChatActivity(key) if key == BaseUI.activeChatTab then return end BaseUI.unread[key] = (BaseUI.unread[key] or 0) + 1 BaseUI.refreshChatTabs() end
-- keep the created gauges in vitalsStats order and packed from the top, -- whatever order their data completed in (a percentage can be ready before -- the hp maxima have arrived) function BaseUI.layoutGauges() local index = 0 for _, stat in ipairs(vitalsStats) do local gauge = BaseUI.gauges[stat.key] if gauge then index = index + 1 gauge:move("0%", layout.gaugeSlots[index]) end end end
function BaseUI.ensureGauge(key) local gauge = BaseUI.gauges[key] if gauge then return gauge end local slot = layout.gaugeSlots[BaseUI.usedGaugeSlots + 1] local def = gaugeDefs[key] if not slot or not def then return nil end BaseUI.usedGaugeSlots = BaseUI.usedGaugeSlots + 1 gauge = Geyser.Gauge:new({ name = "BaseUI_" .. key .. "_gauge", x = "0%", y = slot, width = "100%", height = layout.gaugeHeight, strict = true, font = theme.font, fontSize = 9, }, BaseUI.container) gauge:setStyleSheet(def.front, gaugeBack, gaugeText) gauge:setFgColor("white") gauge:setAlignment("l") gauge:setBold(true) BaseUI.gauges[key] = gauge BaseUI.layoutGauges() return gauge end
local function completeReading(data) if not data then return false end if data.percent then return true end return data.current ~= nil and data.max ~= nil and data.max > 0 end
-- the single entry point every vitals source feeds. snapshot sources (GMCP, -- MSDP) resend everything they know each time, so their stats replace what -- is stored and a transient stat they no longer mention is gone; the prompt -- layer sees one line at a time and merges instead, letting a score screen's -- maxima complete a prompt's bare currents. A source ranked lower than the -- lock's owner is ignored outright. function BaseUI.applyVitals(source, readings, snapshot) local rank = sourceRanks[source] if BaseUI.dormant() or rank < BaseUI.vitalsLock then return end if rank > BaseUI.vitalsLock and completeReading(readings.hp) then -- a better source proved itself with a full hp reading: it takes over -- the lock and everything the previous source reported is dropped BaseUI.vitalsData = {} BaseUI.vitalsLock = rank -- handleDisconnect re-arms these: the next connection may have no protocol if BaseUI.structuredVitalsOwnGauges() then BaseUI.killVitalsTriggers() end end for _, stat in ipairs(vitalsStats) do local reading = readings[stat.key] if snapshot then BaseUI.vitalsData[stat.key] = reading elseif reading and not stat.transient then local data = BaseUI.vitalsData[stat.key] or {} data.current = reading.current or data.current data.max = reading.max or data.max data.percent = reading.percent or data.percent BaseUI.vitalsData[stat.key] = data end end BaseUI.renderVitals() end
function BaseUI.renderVitals() if BaseUI.dormant() then return end local paintable = false for _, stat in ipairs(vitalsStats) do if completeReading(BaseUI.vitalsData[stat.key]) then paintable = true break end end if not paintable and not BaseUI.container then return end BaseUI.build() BaseUI.checkMapData() for _, stat in ipairs(vitalsStats) do -- a gauge is only painted once a full reading is known: either a ready -- percentage, or both a current and a max (maxima are never assumed, so -- a stat may wait for a Maxstats message or a score screen) local data = BaseUI.vitalsData[stat.key] or {} if data.percent then local gauge = BaseUI.ensureGauge(stat.key) if gauge then gauge:setValue(data.percent, 100, string.format("%s %d%%", stat.label, math.floor(data.percent + 0.5))) if gauge.hidden then gauge:show() end end elseif data.current and data.max and data.max > 0 then local gauge = BaseUI.ensureGauge(stat.key) if gauge then gauge:setValue(data.current, data.max, string.format("%s %d/%d", stat.label, data.current, data.max)) if gauge.hidden then gauge:show() end end elseif stat.transient and BaseUI.gauges[stat.key] and not BaseUI.gauges[stat.key].hidden then BaseUI.gauges[stat.key]:hide() end end end
function BaseUI.updateVitals() local sources = {} for _, path in ipairs(vitalsNodes) do local node = gmcpNode(path) if node then sources[#sources + 1] = node end end if not sources[1] then return end BaseUI.sawGmcpVitals = true if BaseUI.dormant() then return end BaseUI.build() BaseUI.checkMapData() local readings = {} for _, stat in ipairs(vitalsStats) do local current, max, percent = statReading(sources, stat) if percent and (percent < 0 or percent > 100) then percent = nil end if current or max or percent then readings[stat.key] = { current = current, max = max, percent = percent } end end BaseUI.applyVitals("gmcp", readings, true) end
function BaseUI.updateMsdpVitals() if type(msdp) ~= "table" then return end local readings = {} for _, stat in ipairs(msdpStats) do -- MSDP delivers numbers as strings more often than not local current = tonumber(msdp[stat.current]) local max = tonumber(msdp[stat.max]) if stat.transient then -- an opponent at zero health (or one no longer reported) is gone if current and current > 0 and max and max > 0 then readings[stat.key] = { current = current, max = max } end elseif current or max then readings[stat.key] = { current = current, max = max } end end if not next(readings) then return end BaseUI.sawMsdpVitals = true BaseUI.applyVitals("msdp", readings, true) end
-- ask the game to keep our vitals variables reported; servers simply ignore -- the ones they do not know function BaseUI.requestMsdpVitals() local variables = {} for _, stat in ipairs(msdpStats) do table.insert(variables, stat.current) table.insert(variables, stat.max) end table.insert(variables, "OPPONENT_NAME") table.insert(variables, "LEVEL") sendMSDP("REPORT", unpack(variables)) end
function BaseUI.enableMsdpVitals(_, protocol) if protocol ~= "MSDP" then return end BaseUI.msdpReady = true if not BaseUI.dormant() then BaseUI.requestMsdpVitals() end end
-- a reconnect (possibly to a different game or character) starts the ladder -- fresh: recurrence counters, the source lock and the one-time score request -- are all per-connection state. Painted gauges keep their last values until -- fresh data arrives. function BaseUI.handleDisconnect() BaseUI.vitalsData = {} BaseUI.vitalsLock = 0 BaseUI.shapeSightings = {} BaseUI.scoreRequested = false BaseUI.scoreWindowUntil = nil BaseUI.sawGmcpVitals = false BaseUI.sawMsdpVitals = false BaseUI.msdpReady = false -- the chat trigger layer retires itself once GMCP chat shows up; the next -- connection may be to a game without it, so re-arm the triggers (the -- first GMCP chat message will retire them again, and the recentCaptures -- ring already covers the echo race that comes with that) BaseUI.gmcpChat = false BaseUI.armChatTriggers() -- only re-arms because the lock was cleared above BaseUI.createVitalsTriggers() end
function BaseUI.addChatMessage() local message = gmcp and gmcp.Comm and gmcp.Comm.Channel and gmcp.Comm.Channel.Text if type(message) ~= "table" or type(message.text) ~= "string" then return end -- the game sends chat over GMCP and usually echoes it as plain text too - -- retire the generic triggers for this session so lines are not captured twice BaseUI.gmcpChat = true BaseUI.disarmChatTriggers() if BaseUI.dormant() then return end BaseUI.build() -- the first GMCP messages race their own plain-text echoes: an echo can be -- trigger-captured moments before this handler learns the game speaks GMCP -- chat, so drop a message whose text was just captured as a line if next(BaseUI.recentCaptures) then local plain = message.text:gsub("\27%[[0-9;:]*m", "") local now = getEpoch() for i = #BaseUI.recentCaptures, 1, -1 do local capture = BaseUI.recentCaptures[i] if now - capture.time > 2 then table.remove(BaseUI.recentCaptures, i) elseif capture.text == plain then table.remove(BaseUI.recentCaptures, i) return end end end local text = ansi2decho(message.text) .. "\n" BaseUI.chats.all:decho(text) BaseUI.noteChatActivity("all") local channel = type(message.channel) == "string" and message.channel:lower() or "" local family = channel:find("tell", 1, true) and "tells" or "channels" BaseUI.chats[family]:decho(text) BaseUI.noteChatActivity(family) end
-- ask the game to send channel text over GMCP (not all games do so unprompted) function BaseUI.enableChannelCapture(_, protocol) if protocol ~= "GMCP" or BaseUI.dormant() then return end gmod.enableModule("BaseUI", "Comm.Channel") end
function BaseUI.maybeAnnounce() if BaseUI.settings.announced then return end -- respect the first-run UI tour: hold the introduction until it is done if mudlet and mudlet.uiTourPending then registerAnonymousEventHandler("sysUiTourFinished", "BaseUI.announce", true) return end BaseUI.announce() end
function BaseUI.announce() -- dormant covers the tour-finished callback arriving after the UI has -- already stepped aside or been hidden - no point introducing it then if BaseUI.settings.announced or BaseUI.dormant() then return end BaseUI.settings.announced = true BaseUI.saveSettings() cecho("\n<cyan>[ Mudlet UI ] Built you a starter interface from what your game supports - health bars, map and chat.\n") cecho("<cyan>[ Mudlet UI ] Drag its title bar to move it, right-click for options, or type <yellow>baseui hide<cyan> to remove it.<reset>\n") end
function BaseUI.hide() BaseUI.settings.hidden = true BaseUI.saveSettings() BaseUI.disarmChatTriggers() BaseUI.killVitalsTriggers() if BaseUI.container then BaseUI.container:hide() BaseUI.container:adjustBorder() end cecho("\n<cyan>[ Mudlet UI ] Hidden - type <yellow>baseui show<cyan> to bring it back.<reset>\n") end
function BaseUI.show() BaseUI.settings.hidden = false BaseUI.settings.standingAside = nil BaseUI.saveSettings() if type(gmcp) == "table" and next(gmcp) then gmod.enableModule("BaseUI", "Comm.Channel") end if BaseUI.msdpReady then BaseUI.requestMsdpVitals() end BaseUI.updateVitals() BaseUI.updateMsdpVitals() BaseUI.armChatTriggers() BaseUI.createVitalsTriggers() BaseUI.renderVitals() if BaseUI.container then BaseUI.container:show() if not BaseUI.container.attached then BaseUI.container:attachToBorder("right") end BaseUI.checkMapData() cecho("\n<cyan>[ Mudlet UI ] Shown.<reset>\n") else cecho("\n<cyan>[ Mudlet UI ] It will appear as soon as the game sends chat or character data.<reset>\n") end end
function BaseUI.alias(input) input = (input or ""):trim():lower() if input == "hide" then BaseUI.hide() elseif input == "show" then BaseUI.show() else local state if BaseUI.settings.hidden then state = "hidden" elseif BaseUI.settings.standingAside then state = "standing aside for the game's own interface" elseif BaseUI.container then state = "shown" else state = "waiting for game data" end cecho("\n<cyan>[ Mudlet UI ] A starter interface built from your game's data (currently " .. state .. ").\n") cecho("<cyan>[ Mudlet UI ] <yellow>baseui hide<cyan> - hide it (remembered between sessions)\n") cecho("<cyan>[ Mudlet UI ] <yellow>baseui show<cyan> - bring it back<reset>\n") end end
BaseUI.loadSettings() -- the chat gates are live from the start (unless the UI is dormant) so the -- interface can appear on the first chat line even on games without GMCP. -- Their tree is imported ahead of this script, and the vitals trigger is -- created after it, so a chat line is routed (and marked as chat) before the -- vitals layer gets a look at it BaseUI.armChatTriggers() BaseUI.createVitalsTriggers() -- negotiate MSDP up front: it costs nothing on servers without it and gives -- gauges to games that have it but lack GMCP setConfig("enableMSDP", true)
registerAnonymousEventHandler("gmcp.Char.Vitals", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.vitals", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Char.Maxstats", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.maxstats", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Char.Status", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.char.status", "BaseUI.updateVitals") registerAnonymousEventHandler("gmcp.Comm.Channel.Text", "BaseUI.addChatMessage") registerAnonymousEventHandler("sysProtocolEnabled", "BaseUI.enableChannelCapture") registerAnonymousEventHandler("sysProtocolEnabled", "BaseUI.enableMsdpVitals") registerAnonymousEventHandler("sysDisconnectionEvent", "BaseUI.handleDisconnect") registerAnonymousEventHandler("sysDataSendRequest", "BaseUI.noteCommandSent") registerAnonymousEventHandler("sysServerGuiInstalled", "BaseUI.standAside") registerAnonymousEventHandler("sysUninstallPackage", "BaseUI.serverGuiRemoved") for _, stat in ipairs(msdpStats) do registerAnonymousEventHandler("msdp." .. stat.current, "BaseUI.updateMsdpVitals") registerAnonymousEventHandler("msdp." .. stat.max, "BaseUI.updateMsdpVitals") end registerAnonymousEventHandler("mapOpenEvent", "BaseUI.checkMapData") registerAnonymousEventHandler("sysMapDownloadEvent", "BaseUI.checkMapData") registerAnonymousEventHandler("sysMapAreaChanged", "BaseUI.checkMapData") registerAnonymousEventHandler("gmcp.Room.Info", "BaseUI.checkMapData") registerAnonymousEventHandler("gmcp.room.info", "BaseUI.checkMapData")
